function renderPricing(){if(!selectedProduct&&products()[0])selectedProduct=S(products()[0].id);const p=product(selectedProduct),rows=Object.keys(cfg.marketplaces).filter(k=>cfg.marketplaces[k]?.active).map(k=>{const c=channelCalc(p,k),approved=currentApproved(p,k),status=c.margin<N(cfg.pricing.minMarginPct)?'<span class="mg-badge mg-danger">Margem baixa</span>':'<span class="mg-badge mg-good">OK</span>';return `<tr><td><b>${esc(c.ch.label)}</b><br><small>${esc(c.ch.source||'Configurável')}</small></td><td>${money(c.base)}</td><td>${pct(c.commission+c.payment+c.tax)}</td><td>${money(c.logistics+c.monthlyPerOrder+c.pack)}</td><td>${money(c.profit)}<br>${pct(c.margin)} ${status}</td><td>${money(c.minPrice)}</td><td><b>${money(c.recommended)}</b></td><td>${money(c.strategic)}</td><td>${approved?money(approved):'—'}</td><td><div class="mg-actions"><button class="mg-btn mg-primary" data-approve-price="${k}" data-price="${c.recommended}">Recomendado</button><button class="mg-btn mg-soft" data-approve-price="${k}" data-price="${c.strategic}">Estratégico</button><button class="mg-btn mg-soft" data-custom-price="${k}">Outro valor</button></div></td></tr>`}).join('');return `<div class="mg-panel"><div class="mg-row"><div class="mg-field w6"><label>Produto</label><select id="mgProduct">${optionProducts()}</select></div><div class="mg-field"><label>Margem alvo %</label><input id="mgTargetMargin" type="number" step="0.1" value="${N(cfg.pricing.targetMarginPct)}"></div><div class="mg-field"><label>Margem mínima %</label><input id="mgMinMargin" type="number" step="0.1" value="${N(cfg.pricing.minMarginPct)}"></div></div><div class="mg-note" style="margin-top:10px">${esc(name(p))} · custo ${money(cost(p))} · preço base ${money(sale(p))}. Preços de Loja, E-commerce, WhatsApp, iFood e 99 ficam independentes.</div></div><div class="mg-panel mg-scroll"><table class="mg-table"><thead><tr><th>Canal</th><th>Atual</th><th>Taxas</th><th>Fixos/logística</th><th>Resultado</th><th>Mínimo</th><th>Recomendado</th><th>Estratégico</th><th>Aprovado</th><th>Ação</th></tr></thead><tbody>${rows}</tbody></table></div><div class="mg-panel"><button class="mg-btn mg-soft" id="mgExportPricing">Exportar preços CSV</button></div>`}
function renderFees(){const rows=Object.entries(cfg.marketplaces).map(([k,ch])=>`<tr><td><input data-ch="${k}" data-f="label" value="${esc(ch.label)}"></td><td><input data-ch="${k}" data-f="commissionPct" type="number" step="0.01" value="${N(ch.commissionPct)}"></td><td><input data-ch="${k}" data-f="paymentPct" type="number" step="0.01" value="${N(ch.paymentPct)}"></td><td><input data-ch="${k}" data-f="monthlyFee" type="number" step="0.01" value="${N(ch.monthlyFee)}"></td><td><input data-ch="${k}" data-f="monthlyThreshold" type="number" step="0.01" value="${N(ch.monthlyThreshold)}"></td><td><select data-ch="${k}" data-f="logisticsMode"><option value="OWN" ${ch.logisticsMode==='OWN'?'selected':''}>Motoboy próprio</option><option value="PLATFORM" ${ch.logisticsMode==='PLATFORM'?'selected':''}>Plataforma</option></select></td><td><input data-ch="${k}" data-f="logisticsCost" type="number" step="0.01" value="${N(ch.logisticsCost)}"></td><td><input data-ch="${k}" data-f="active" type="checkbox" ${ch.active!==false?'checked':''}></td><td>${ch.contractRequired?'<span class="mg-badge mg-warn">Confirmar contrato</span>':'<span class="mg-badge mg-good">Padrão</span>'}</td></tr>`).join('');return `<div class="mg-panel"><h3>iFood, 99Food e demais canais</h3><div class="mg-note">Todas as taxas são parametrizadas. Você pode substituir os valores pelo seu contrato real sem alterar código.</div><div class="mg-scroll"><table class="mg-table"><thead><tr><th>Canal</th><th>Comissão %</th><th>Pagamento %</th><th>Mensalidade</th><th>Faixa mensalidade</th><th>Logística</th><th>Custo logístico</th><th>Ativo</th><th>Origem</th></tr></thead><tbody>${rows}</tbody></table></div></div><div class="mg-panel"><h3>Premissas</h3><div class="mg-row"><div class="mg-field"><label>Pedidos/mês</label><input id="mgMonthlyOrders" type="number" value="${N(cfg.pricing.monthlyOrdersEstimate)}"></div><div class="mg-field"><label>Motoboy médio</label><input id="mgMotoboy" type="number" step="0.01" value="${N(cfg.pricing.motoboyAverageCost)}"></div><div class="mg-field"><label>Frete cobrado cliente</label><input id="mgFreightCharged" type="number" step="0.01" value="${N(cfg.pricing.averageFreightCharged)}"></div><div class="mg-field"><label>Embalagem média</label><input id="mgPackaging" type="number" step="0.01" value="${N(cfg.pricing.packagingAverageCost)}"></div><div class="mg-field"><label>Tributos %</label><input id="mgTaxPct" type="number" step="0.01" value="${N(cfg.pricing.taxPct)}"></div><div class="mg-field"><label>Final psicológico</label><select id="mgEnding"><option ${S(cfg.pricing.psychologicalEnding)==='90'?'selected':''}>90</option><option ${S(cfg.pricing.psychologicalEnding)==='99'?'selected':''}>99</option><option ${S(cfg.pricing.psychologicalEnding)==='50'?'selected':''}>50</option></select></div></div></div>`}
function renderAlerts(){const al=alerts();return `<div class="mg-panel"><h3>Central de Alertas e Exceções</h3><div class="mg-row">${[['mgAlertStock','Estoque mínimo','stockMin'],['mgAlertMargin','Margem','margin'],['mgAlertOrders','Pedidos','orders'],['mgAlertFinance','Financeiro','finance'],['mgAlertExpiry','Validade/FEFO','expiry'],['mgAlertIntegration','Integração','integration'],['mgAlertCatalog','Catálogo','catalog'],['mgAlertTasks','Tarefas','tasks']].map(([id,l,k])=>`<div class="mg-field"><label><input id="${id}" type="checkbox" ${cfg.alerts[k]?'checked':''}> ${l}</label></div>`).join('')}</div></div><div class="mg-panel">${al.length?al.map(a=>`<div class="mg-note" style="margin:6px 0"><span class="mg-badge mg-${a.level}">${a.type}</span> ${esc(a.text)}</div>`).join(''):'Nenhum alerta.'}</div>`}
function renderPcp(){const rows=products().map(p=>{const d=demandFor(p),need=Math.max(0,(maxStock(p)||d.week*(1+N(cfg.purchases.safetyPct)/100))-stock(p));return{p,d,need}}).filter(x=>x.d.suggest>0||x.need>0).sort((a,b)=>b.d.suggest-a.d.suggest).slice(0,100);return `<div class="mg-panel"><h3>Previsão de demanda + PCP + Compras inteligentes</h3><div class="mg-row"><div class="mg-field"><label>Histórico (dias)</label><input id="mgHistoryDays" type="number" min="7" value="${N(cfg.forecast.historyDays)}"></div><div class="mg-field"><label>Segurança previsão %</label><input id="mgForecastSafety" type="number" step="0.1" value="${N(cfg.forecast.safetyPct)}"></div><div class="mg-field"><label>Segurança compras %</label><input id="mgPurchaseSafety" type="number" step="0.1" value="${N(cfg.purchases.safetyPct)}"></div><div class="mg-field"><button class="mg-btn mg-primary" id="mgCreatePcpTasks">Criar tarefas das sugestões</button></div></div></div><div class="mg-panel mg-scroll"><table class="mg-table"><thead><tr><th>Produto</th><th>Estoque</th><th>Média/dia</th><th>Previsão 7d</th><th>Produzir</th><th>Comprar/repor</th><th>Custo</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(name(x.p))}</td><td>${stock(x.p).toFixed(2)}</td><td>${x.d.daily.toFixed(2)}</td><td>${x.d.week.toFixed(2)}</td><td><b>${x.d.suggest.toFixed(2)}</b></td><td>${x.need.toFixed(2)}</td><td>${money(cost(x.p)*x.need)}</td></tr>`).join('')||'<tr><td colspan="7">Sem necessidade calculada.</td></tr>'}</tbody></table></div>`}
function renderFinance(){if(!selectedProduct&&products()[0])selectedProduct=S(products()[0].id);const p=product(selectedProduct),rows=Object.keys(cfg.marketplaces).filter(k=>cfg.marketplaces[k]?.active).map(k=>{const c=channelCalc(p,k);return `<tr><td>${esc(c.ch.label)}</td><td>${money(c.base)}</td><td>${money(c.c)}</td><td>${money(c.base*(c.commission+c.payment+c.tax)/100)}</td><td>${money(c.logistics+c.monthlyPerOrder+c.pack)}</td><td><b>${money(c.profit)}</b></td><td>${pct(c.margin)}</td></tr>`}).join(''),proj=[7,15,30,60,90].map(d=>`<div class="mg-kpi"><small>Fluxo ${d} dias</small><b>${money(cashProjection(d))}</b></div>`).join(''),vs=salesSince(30),actual={revenue:salesValue(vs),cmv:salesCmv(vs)},bud=cfg.budget||{};return `<div class="mg-panel"><h3>Margem real por canal</h3><select id="mgFinanceProduct">${optionProducts()}</select><div class="mg-scroll" style="margin-top:10px"><table class="mg-table"><thead><tr><th>Canal</th><th>Venda</th><th>CMV</th><th>Taxas</th><th>Logística/fixos</th><th>Resultado</th><th>Margem</th></tr></thead><tbody>${rows}</tbody></table></div></div><div class="mg-panel"><h3>Fluxo de caixa projetado</h3><div class="mg-grid">${proj}</div></div><div class="mg-panel"><h3>Orçado x realizado (30 dias)</h3><div class="mg-row"><div class="mg-field"><label>Receita orçada</label><input id="mgBudgetRevenue" type="number" value="${N(bud.monthlyRevenue)}"></div><div class="mg-field"><label>CMV orçado</label><input id="mgBudgetCmv" type="number" value="${N(bud.monthlyCmv)}"></div><div class="mg-field"><label>Despesas orçadas</label><input id="mgBudgetExp" type="number" value="${N(bud.monthlyExpenses)}"></div><div class="mg-field"><b>Receita realizada ${money(actual.revenue)}</b><br><small>CMV ${money(actual.cmv)}</small></div></div></div><div class="mg-panel"><h3>Fechamento diário</h3><div class="mg-row"><div class="mg-field"><label>Data</label><input id="mgCloseDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="mg-field"><label>Saldo caixa informado</label><input id="mgCloseCash" type="number" step="0.01"></div><div class="mg-field"><label>Observação</label><input id="mgCloseNote"></div><div class="mg-field"><button id="mgAddClosing" class="mg-btn mg-primary">Registrar fechamento</button></div></div>${A(cfg.financialClosings).slice(-5).reverse().map(x=>`<div class="mg-note" style="margin-top:6px"><b>${esc(x.date)}</b> · caixa ${money(x.cash)} · ${esc(x.actor)} · ${esc(x.note||'')}</div>`).join('')}</div><div class="mg-panel"><h3>Conciliação PIX / cartão / plataforma</h3><div class="mg-row"><div class="mg-field"><label>Origem</label><select id="mgRecSource"><option>PIX</option><option>Crédito</option><option>Débito</option><option>iFood</option><option>99Food</option><option>Outro</option></select></div><div class="mg-field"><label>Esperado</label><input id="mgRecExpected" type="number" step="0.01"></div><div class="mg-field"><label>Recebido</label><input id="mgRecReceived" type="number" step="0.01"></div><div class="mg-field"><button id="mgAddRec" class="mg-btn mg-primary">Conciliar</button></div></div>${A(cfg.reconciliations).slice(-6).reverse().map(x=>`<div class="mg-note" style="margin-top:6px"><b>${esc(x.source)}</b> · esperado ${money(x.expected)} · recebido ${money(x.received)} · diferença ${money(N(x.received)-N(x.expected))}</div>`).join('')}</div><div class="mg-panel"><h3>Centros de custo</h3><div class="mg-actions">${A(cfg.costCenters).map(x=>`<span class="mg-badge mg-soft">${esc(typeof x==='string'?x:x.name)}</span>`).join('')}</div><div class="mg-row" style="margin-top:10px"><div class="mg-field w6"><label>Novo centro</label><input id="mgCostCenterName"></div><div class="mg-field"><button id="mgAddCostCenter" class="mg-btn mg-primary">Adicionar</button></div></div></div>`}
function renderApproval(){return `<div class="mg-panel"><h3>Workflow de aprovação</h3><div class="mg-row"><div class="mg-field"><label>Desconto acima de %</label><input id="mgApDiscount" type="number" step="0.1" value="${N(cfg.approval.discountPct)}"></div><div class="mg-field"><label>Margem abaixo de %</label><input id="mgApMargin" type="number" step="0.1" value="${N(cfg.approval.minMarginPct)}"></div><div class="mg-field"><label>Ajuste estoque acima R$</label><input id="mgApStock" type="number" value="${N(cfg.approval.stockAdjustmentValue)}"></div><div class="mg-field"><label>Compra acima R$</label><input id="mgApPurchase" type="number" value="${N(cfg.approval.purchaseValue)}"></div><div class="mg-field"><label>Alteração preço acima %</label><input id="mgApPrice" type="number" value="${N(cfg.approval.priceChangePct)}"></div></div></div><div class="mg-panel"><h3>Solicitar aprovação</h3><div class="mg-row"><div class="mg-field"><label>Tipo</label><select id="mgReqType"><option>DESCONTO</option><option>PREÇO</option><option>COMPRA</option><option>ESTOQUE</option><option>CRÉDITO</option></select></div><div class="mg-field w6"><label>Descrição</label><input id="mgReqDesc"></div><div class="mg-field"><label>Valor</label><input id="mgReqValue" type="number" step="0.01"></div><div class="mg-field"><button id="mgAddApproval" class="mg-btn mg-primary">Solicitar</button></div></div></div><div class="mg-panel mg-scroll"><table class="mg-table"><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Valor</th><th>Status</th><th>Ação</th></tr></thead><tbody>${A(cfg.approvalRequests).slice().reverse().map(r=>`<tr><td>${esc(S(r.at).slice(0,19))}</td><td>${esc(r.type)}</td><td>${esc(r.desc)}</td><td>${money(r.value)}</td><td>${esc(r.status)}</td><td>${r.status==='PENDENTE'?`<button class="mg-btn mg-good" data-appr="${esc(r.id)}">Aprovar</button> <button class="mg-btn mg-danger" data-rej="${esc(r.id)}">Rejeitar</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6">Nenhuma solicitação.</td></tr>'}</tbody></table></div>`}
function renderAutomation(){return `<div class="mg-panel"><h3>Motor SE → ENTÃO</h3><div class="mg-row"><div class="mg-field"><label>Se</label><select id="mgRuleIf"><option>ESTOQUE_ABAIXO_MINIMO</option><option>MARGEM_ABAIXO_MINIMA</option><option>PEDIDO_ECOMMERCE_NOVO</option><option>CONTA_VENCE_AMANHA</option><option>CLIENTE_INATIVO_60_DIAS</option><option>VALIDADE_PROXIMA</option><option>CATALOGO_INCOMPLETO</option></select></div><div class="mg-field w6"><label>Então</label><select id="mgRuleThen"><option>CRIAR_ALERTA</option><option>CRIAR_TAREFA</option><option>CRIAR_SUGESTAO_COMPRA</option><option>CRIAR_SEPARACAO</option><option>ENVIAR_PARA_CRM</option></select></div><div class="mg-field"><button id="mgAddRule" class="mg-btn mg-primary">Adicionar</button></div><div class="mg-field"><button id="mgRunRules" class="mg-btn mg-soft">Executar regras agora</button></div></div></div><div class="mg-panel mg-scroll"><table class="mg-table"><thead><tr><th>Condição</th><th>Ação</th><th>Status</th><th></th></tr></thead><tbody>${A(cfg.automationRules).map(r=>`<tr><td>${esc(r.if)}</td><td>${esc(r.then)}</td><td>${r.active!==false?'Ativa':'Inativa'}</td><td><button class="mg-btn mg-danger" data-del-rule="${esc(r.id)}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma regra.</td></tr>'}</tbody></table></div>`}
function renderQuality(){const lots=A(cfg.lots).slice().sort((a,b)=>S(a.expiry).localeCompare(S(b.expiry))),losses=A(cfg.losses);return `<div class="mg-panel"><h3>Lotes, validade e FEFO</h3><div class="mg-row"><div class="mg-field w6"><label>Produto</label><select id="mgLotProduct">${optionProducts()}</select></div><div class="mg-field"><label>Lote</label><input id="mgLotCode"></div><div class="mg-field"><label>Fabricação</label><input id="mgLotMade" type="date"></div><div class="mg-field"><label>Validade</label><input id="mgLotExpiry" type="date"></div><div class="mg-field"><label>Quantidade</label><input id="mgLotQty" type="number" step="0.001"></div><div class="mg-field"><button id="mgAddLot" class="mg-btn mg-primary">Adicionar lote</button></div></div></div><div class="mg-panel mg-scroll"><table class="mg-table"><thead><tr><th>Produto</th><th>Lote</th><th>Fabricação</th><th>Validade</th><th>Qtd.</th><th>FEFO</th></tr></thead><tbody>${lots.map((l,i)=>`<tr><td>${esc(name(product(l.productId)))}</td><td>${esc(l.code)}</td><td>${esc(l.made)}</td><td>${esc(l.expiry)}</td><td>${N(l.qty)}</td><td>${i===0?'<span class="mg-badge mg-warn">Usar primeiro</span>':expiryDays(l)+'d'}</td></tr>`).join('')||'<tr><td colspan="6">Sem lotes.</td></tr>'}</tbody></table></div><div class="mg-panel"><h3>Rastreabilidade</h3><div class="mg-row"><div class="mg-field"><label>Lote</label><select id="mgTraceLot">${lots.map(l=>`<option value="${esc(l.id)}">${esc(l.code)} · ${esc(name(product(l.productId)))}</option>`).join('')}</select></div><div class="mg-field"><label>Pedido / referência</label><input id="mgTraceOrder"></div><div class="mg-field w6"><label>Cliente / observação</label><input id="mgTraceNote"></div><div class="mg-field"><button id="mgAddTrace" class="mg-btn mg-primary">Vincular</button></div></div>${A(cfg.traceability).slice(-6).reverse().map(x=>`<div class="mg-note" style="margin-top:6px"><b>${esc(x.order)}</b> · lote ${esc(lots.find(l=>S(l.id)===S(x.lotId))?.code||x.lotId)} · ${esc(x.note||'')}</div>`).join('')}</div><div class="mg-panel"><h3>Gestão de perdas</h3><div class="mg-row"><div class="mg-field w6"><label>Produto</label><select id="mgLossProduct">${optionProducts()}</select></div><div class="mg-field"><label>Motivo</label><select id="mgLossReason">${A(cfg.lossReasons).map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="mg-field"><label>Quantidade</label><input id="mgLossQty" type="number" step="0.001"></div><div class="mg-field"><label>Valor</label><input id="mgLossValue" type="number" step="0.01"></div><div class="mg-field"><button id="mgAddLoss" class="mg-btn mg-primary">Registrar perda</button></div></div><div class="mg-note" style="margin-top:10px">Perdas: ${losses.length} · ${money(losses.reduce((s,x)=>s+N(x.value),0))}</div></div>`}
function renderOps(){return `<div class="mg-panel"><h3>Central de tarefas</h3><div class="mg-row"><div class="mg-field w6"><label>Tarefa</label><input id="mgTaskText"></div><div class="mg-field"><label>Responsável</label><input id="mgTaskOwner"></div><div class="mg-field"><label>Prazo</label><input id="mgTaskDue" type="datetime-local"></div><div class="mg-field"><button id="mgAddTask" class="mg-btn mg-primary">Adicionar</button></div></div>${A(cfg.tasks).slice().reverse().map(t=>`<div class="mg-note" style="margin-top:6px"><b>${esc(t.text)}</b> · ${esc(t.owner||'Sem responsável')} · ${esc(t.due||'Sem prazo')} · ${t.done?'Concluída':'Pendente'} ${!t.done?`<button class="mg-btn mg-good" data-done-task="${esc(t.id)}">Concluir</button>`:''}</div>`).join('')}</div><div class="mg-panel"><h3>Checklists operacionais</h3><div class="mg-row"><div class="mg-field"><label>Tipo</label><select id="mgCheckType"><option>ABERTURA</option><option>PRODUCAO</option><option>FECHAMENTO</option></select></div><div class="mg-field w6"><label>Conferência</label><input id="mgCheckNote" placeholder="Temperatura, limpeza, caixa, estoque..."></div><div class="mg-field"><button id="mgAddCheck" class="mg-btn mg-primary">Registrar</button></div></div>${A(cfg.checklistRuns).slice(-8).reverse().map(x=>`<div class="mg-note" style="margin-top:6px"><b>${esc(x.type)}</b> · ${esc(x.at)} · ${esc(x.actor)} · ${esc(x.note)}</div>`).join('')}</div><div class="mg-panel"><h3>Ativos e manutenção</h3><div class="mg-row"><div class="mg-field w6"><label>Equipamento</label><input id="mgEqName"></div><div class="mg-field"><label>Próxima manutenção</label><input id="mgEqNext" type="date"></div><div class="mg-field"><label>Custo previsto</label><input id="mgEqCost" type="number" step="0.01"></div><div class="mg-field"><button id="mgAddEq" class="mg-btn mg-primary">Cadastrar</button></div></div>${A(cfg.equipment).map(x=>`<div class="mg-note" style="margin-top:6px"><b>${esc(x.name)}</b> · próxima ${esc(x.next||'—')} · ${money(x.cost)}</div>`).join('')}</div>`}
function answerQuestion(q){const t=S(q).toLowerCase();if(!t)return'Faça uma pergunta.';if(t.includes('ticket'))return`Ticket médio dos últimos 90 dias: ${money(summary.averageTicket)}.`;if(t.includes('vendi')||t.includes('fatur'))return`Faturamento dos últimos 90 dias: ${money(summary.revenue)}. Hoje: ${money(summary.todayRevenue||todayLocal().revenue)}.`;if(t.includes('estoque')){const ps=products().filter(p=>minStock(p)>0&&stock(p)<minStock(p));return ps.length?`Abaixo do mínimo: ${ps.slice(0,10).map(name).join(', ')}.`:'Não encontrei produtos abaixo do mínimo.'}if(t.includes('margem')){let w=null;for(const p of products())for(const k of Object.keys(cfg.marketplaces)){const c=channelCalc(p,k);if(c.base>0&&(!w||c.margin<w.margin))w={p,k,margin:c.margin,ch:c.ch,rec:c.recommended}}return w?`Pior margem: ${name(w.p)} em ${w.ch.label}, ${w.margin.toFixed(1)}%. Recomendado ${money(w.rec)}.`:'Sem dados.'}if(t.includes('produz')){const arr=products().map(p=>({p,d:demandFor(p)})).filter(x=>x.d.suggest>0).sort((a,b)=>b.d.suggest-a.d.suggest);return arr.length?'Produção sugerida: '+arr.slice(0,6).map(x=>`${name(x.p)} ${x.d.suggest.toFixed(1)}`).join(' · ')+'.':'Sem necessidade calculada.'}if(t.includes('pedido'))return`Há ${N(summary.pending)} pedido(s) pendente(s).`;if(t.includes('catalog')||t.includes('imagem')){const c=catalogStats();return`Há ${c.online} produtos online, ${c.missingImg.length} sem imagem e ${c.missingCat.length} sem categoria.`}return'Posso responder sobre faturamento, ticket médio, estoque, margem, produção, pedidos e catálogo.'}
function renderAssistant(){return `<div class="mg-panel"><h3>🤖 Pergunte ao John</h3><div class="mg-note">Consulta em modo leitura. Não altera dados sem ação explícita.</div><div class="mg-row" style="margin-top:10px"><div class="mg-field w12"><label>Pergunta</label><input id="mgQuestion" placeholder="Ex.: O que preciso produzir amanhã?"></div><div class="mg-field"><button id="mgAsk" class="mg-btn mg-primary">Perguntar</button></div></div><div id="mgAnswer" class="mg-note" style="margin-top:10px">Faça uma pergunta.</div></div>`}
function renderHealth(){const cs=catalogStats(),aud=A(summary.recentAudit);return `<div class="mg-grid"><div class="mg-kpi"><small>API</small><b>${summary.health?.api?'🟢 OK':'🔴'}</b></div><div class="mg-kpi"><small>Banco</small><b>${summary.health?.database?'🟢 OK':'🔴'}</b></div><div class="mg-kpi"><small>Produtos API</small><b>${N(summary.products)}</b></div><div class="mg-kpi"><small>Online ERP</small><b>${cs.online}</b></div><div class="mg-kpi"><small>Sem imagem</small><b>${cs.missingImg.length}</b></div><div class="mg-kpi"><small>Sem categoria</small><b>${cs.missingCat.length}</b></div></div><div class="mg-panel"><div class="mg-actions"><button class="mg-btn mg-primary" id="mgRepairCatalog">Reconciliar catálogo e publicar</button><button class="mg-btn mg-soft" id="mgRunHealth">Atualizar saúde</button></div><div class="mg-note" style="margin-top:10px">Último pedido: ${esc(S(summary.health?.lastOrderAt||'—').slice(0,19))} · último evento: ${esc(S(summary.health?.lastEventAt||'—').slice(0,19))}</div></div><div class="mg-panel"><h3>Auditoria recente</h3><div class="mg-scroll"><table class="mg-table"><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Detalhe</th></tr></thead><tbody>${aud.slice(0,100).map(a=>`<tr><td>${esc(S(a.created_at).slice(0,19))}</td><td>${esc(a.detail?.actor||'ERP')}</td><td>${esc(a.detail?.action||'—')}</td><td>${esc(JSON.stringify(a.detail?.detail||{}).slice(0,260))}</td></tr>`).join('')||'<tr><td colspan="4">Sem auditoria.</td></tr>'}</tbody></table></div></div>`}
function render(){ensurePage();renderTabs();const map={cockpit:renderCockpit,pricing:renderPricing,fees:renderFees,alerts:renderAlerts,pcp:renderPcp,finance:renderFinance,approval:renderApproval,automation:renderAutomation,quality:renderQuality,ops:renderOps,assistant:renderAssistant,health:renderHealth};E('mg822Body').innerHTML=(map[tab]||renderCockpit)();bind()}
function absorb(){if(E('mgBudgetRevenue'))cfg.budget={monthlyRevenue:N(E('mgBudgetRevenue').value),monthlyCmv:N(E('mgBudgetCmv').value),monthlyExpenses:N(E('mgBudgetExp').value)};if(E('mgTargetMargin'))cfg.pricing.targetMarginPct=N(E('mgTargetMargin').value);if(E('mgMinMargin'))cfg.pricing.minMarginPct=N(E('mgMinMargin').value);if(E('mgMonthlyOrders'))cfg.pricing.monthlyOrdersEstimate=N(E('mgMonthlyOrders').value);if(E('mgMotoboy'))cfg.pricing.motoboyAverageCost=N(E('mgMotoboy').value);if(E('mgFreightCharged'))cfg.pricing.averageFreightCharged=N(E('mgFreightCharged').value);if(E('mgPackaging'))cfg.pricing.packagingAverageCost=N(E('mgPackaging').value);if(E('mgTaxPct'))cfg.pricing.taxPct=N(E('mgTaxPct').value);if(E('mgEnding'))cfg.pricing.psychologicalEnding=E('mgEnding').value;if(E('mgHistoryDays')){cfg.forecast.historyDays=N(E('mgHistoryDays').value);cfg.forecast.safetyPct=N(E('mgForecastSafety').value);cfg.purchases.safetyPct=N(E('mgPurchaseSafety').value)}if(E('mgApDiscount'))cfg.approval={...cfg.approval,discountPct:N(E('mgApDiscount').value),minMarginPct:N(E('mgApMargin').value),stockAdjustmentValue:N(E('mgApStock').value),purchaseValue:N(E('mgApPurchase').value),priceChangePct:N(E('mgApPrice').value)};const amap={mgAlertStock:'stockMin',mgAlertMargin:'margin',mgAlertOrders:'orders',mgAlertFinance:'finance',mgAlertExpiry:'expiry',mgAlertIntegration:'integration',mgAlertCatalog:'catalog',mgAlertTasks:'tasks'};for(const [id,k] of Object.entries(amap))if(E(id))cfg.alerts[k]=E(id).checked;document.querySelectorAll('[data-ch][data-f]').forEach(i=>{const ch=cfg.marketplaces[i.dataset.ch]||(cfg.marketplaces[i.dataset.ch]={}),f=i.dataset.f;if(f==='active')ch[f]=i.checked;else ch[f]=['commissionPct','paymentPct','monthlyFee','monthlyThreshold','logisticsCost'].includes(f)?N(i.value):i.value})}
async function saveConfig(quiet=false){if(saving)return;saving=true;try{absorb();const r=await api('/api/v1/admin/management-engine',{method:'PUT',body:JSON.stringify(cfg)});cfg=mergeConfig(r.config||cfg);await syncEcommerce('save-config');audit('CONFIG_GESTAO_SALVA',{version:'8.22.0'});if(!quiet)toast('Central Gerencial salva e sincronizada com o E-commerce.');render()}catch(e){if(!quiet)toast('Falha ao salvar: '+e.message);else console.warn(e)}finally{saving=false}}
async function approvePrice(key,price){absorb();const p=product(selectedProduct);if(!p.id)return;const old=currentApproved(p,key)||channelCalc(p,key).base;cfg.productPricing[p.id]=cfg.productPricing[p.id]||{};cfg.productPricing[p.id][key]={approvedPrice:N(price),approvedAt:new Date().toISOString(),approvedBy:actor(),previousPrice:old};p.precosCanais=p.precosCanais||{};p.precosCanais[key]=N(price);if(key==='ECOMMERCE'){p.ecommerce=p.ecommerce&&typeof p.ecommerce==='object'?p.ecommerce:{};p.ecommerce.precoEcommerce=N(price);p.precoEcommerce=N(price);p.ecommercePrice=N(price)}p.atualizadoEm=new Date().toISOString();saveLocal();audit('PRECO_CANAL_APROVADO',{productId:p.id,produto:name(p),canal:key,precoAnterior:old,precoNovo:N(price)});await saveConfig(true);await syncEcommerce('approved-price');toast(`Preço ${money(price)} aprovado para ${cfg.marketplaces[key].label}.`)}
function exportPricing(){const rows=[['codigo','produto','canal','preco_aprovado','aprovado_em','aprovado_por']];for(const p of products())for(const [k,v] of Object.entries(cfg.productPricing?.[p.id]||{}))if(N(v.approvedPrice)>0)rows.push([p.codigo||'',name(p),k,N(v.approvedPrice).toFixed(2),v.approvedAt||'',v.approvedBy||'']);const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+S(x).replace(/"/g,'""')+'"').join(';')).join('\n'),b=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='john_precos_multicanal.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function runAutomation(){cfg.runtimeAlerts=[];let created=0;for(const r of A(cfg.automationRules).filter(x=>x.active!==false)){let hit=false,msg='';if(r.if==='ESTOQUE_ABAIXO_MINIMO'){const p=products().find(p=>minStock(p)>0&&stock(p)<minStock(p));if(p){hit=true;msg=`Estoque baixo: ${name(p)}`}}else if(r.if==='MARGEM_ABAIXO_MINIMA'){outer:for(const p of products())for(const k of Object.keys(cfg.marketplaces)){const c=channelCalc(p,k);if(c.base>0&&c.margin<N(cfg.pricing.minMarginPct)){hit=true;msg=`Margem baixa: ${name(p)} · ${c.ch.label}`;break outer}}}else if(r.if==='PEDIDO_ECOMMERCE_NOVO'&&N(summary.pending)>0){hit=true;msg=`${N(summary.pending)} pedido(s) E-commerce pendente(s)`}else if(r.if==='VALIDADE_PROXIMA'){const l=A(cfg.lots).find(x=>expiryDays(x)<=3);if(l){hit=true;msg=`Validade próxima: lote ${l.code}`}}else if(r.if==='CATALOGO_INCOMPLETO'){const c=catalogStats();if(c.missingImg.length||c.missingCat.length){hit=true;msg=`Catálogo: ${c.missingImg.length} sem imagem, ${c.missingCat.length} sem categoria`}}if(hit){if(r.then==='CRIAR_TAREFA'){if(!A(cfg.tasks).some(t=>!t.done&&t.text===msg)){cfg.tasks.push({id:uid(),text:msg,owner:'',due:'',done:false,createdAt:new Date().toISOString(),source:'AUTOMACAO'});created++}}else{cfg.runtimeAlerts.push({level:'warn',type:'AUTOMAÇÃO',text:msg+' → '+r.then});created++}}}audit('AUTOMACOES_EXECUTADAS',{created});saveConfig(true);toast(`${created} ação(ões) de automação gerada(s).`);render()}
function bind(){E('mgProduct')?.addEventListener('change',e=>{selectedProduct=e.target.value;render()});E('mgFinanceProduct')?.addEventListener('change',e=>{selectedProduct=e.target.value;render()});document.querySelectorAll('[data-approve-price]').forEach(b=>b.onclick=()=>approvePrice(b.dataset.approvePrice,b.dataset.price));document.querySelectorAll('[data-custom-price]').forEach(b=>b.onclick=()=>{const c=prompt('Informe o preço aprovado para '+cfg.marketplaces[b.dataset.customPrice].label,channelCalc(product(selectedProduct),b.dataset.customPrice).recommended.toFixed(2));if(c!==null&&N(c)>0)approvePrice(b.dataset.customPrice,N(c))});E('mgExportPricing')&&(E('mgExportPricing').onclick=exportPricing);E('mgCreatePcpTasks')&&(E('mgCreatePcpTasks').onclick=()=>{let n=0;for(const p of products()){const d=demandFor(p);if(d.suggest>0&&!A(cfg.tasks).some(t=>!t.done&&t.source==='PCP'&&S(t.productId)===S(p.id))){cfg.tasks.push({id:uid(),text:`Produzir ${d.suggest.toFixed(2)} de ${name(p)}`,owner:'Produção',due:'',done:false,source:'PCP',productId:p.id});n++}}saveConfig(true);toast(`${n} tarefa(s) de produção criada(s).`);render()});E('mgAddClosing')&&(E('mgAddClosing').onclick=()=>{cfg.financialClosings.push({id:uid(),date:E('mgCloseDate').value,cash:N(E('mgCloseCash').value),note:S(E('mgCloseNote').value),actor:actor(),at:new Date().toISOString()});audit('FECHAMENTO_DIARIO',cfg.financialClosings.at(-1));saveConfig(true);render()});E('mgAddRec')&&(E('mgAddRec').onclick=()=>{cfg.reconciliations.push({id:uid(),source:E('mgRecSource').value,expected:N(E('mgRecExpected').value),received:N(E('mgRecReceived').value),actor:actor(),at:new Date().toISOString()});audit('CONCILIACAO',cfg.reconciliations.at(-1));saveConfig(true);render()});E('mgAddCostCenter')&&(E('mgAddCostCenter').onclick=()=>{const x=S(E('mgCostCenterName').value).trim();if(x&&!cfg.costCenters.some(y=>S(typeof y==='string'?y:y.name).toLowerCase()===x.toLowerCase()))cfg.costCenters.push(x);saveConfig(true);render()});E('mgAddApproval')&&(E('mgAddApproval').onclick=()=>{cfg.approvalRequests.push({id:uid(),type:E('mgReqType').value,desc:S(E('mgReqDesc').value),value:N(E('mgReqValue').value),status:'PENDENTE',requestedBy:actor(),at:new Date().toISOString()});audit('APROVACAO_SOLICITADA',cfg.approvalRequests.at(-1));saveConfig(true);render()});document.querySelectorAll('[data-appr]').forEach(b=>b.onclick=()=>{const r=cfg.approvalRequests.find(x=>S(x.id)===S(b.dataset.appr));if(r){r.status='APROVADO';r.decidedBy=actor();r.decidedAt=new Date().toISOString();audit('APROVACAO_APROVADA',r);saveConfig(true);render()}});document.querySelectorAll('[data-rej]').forEach(b=>b.onclick=()=>{const r=cfg.approvalRequests.find(x=>S(x.id)===S(b.dataset.rej));if(r){r.status='REJEITADO';r.decidedBy=actor();r.decidedAt=new Date().toISOString();audit('APROVACAO_REJEITADA',r);saveConfig(true);render()}});E('mgAddRule')&&(E('mgAddRule').onclick=()=>{cfg.automationRules.push({id:uid(),if:E('mgRuleIf').value,then:E('mgRuleThen').value,active:true});saveConfig(true);render()});E('mgRunRules')&&(E('mgRunRules').onclick=runAutomation);document.querySelectorAll('[data-del-rule]').forEach(b=>b.onclick=()=>{cfg.automationRules=cfg.automationRules.filter(x=>S(x.id)!==S(b.dataset.delRule));saveConfig(true);render()});E('mgAddLot')&&(E('mgAddLot').onclick=()=>{cfg.lots.push({id:uid(),productId:E('mgLotProduct').value,code:S(E('mgLotCode').value),made:E('mgLotMade').value,expiry:E('mgLotExpiry').value,qty:N(E('mgLotQty').value),createdAt:new Date().toISOString()});audit('LOTE_CADASTRADO',cfg.lots.at(-1));saveConfig(true);render()});E('mgAddTrace')&&(E('mgAddTrace').onclick=()=>{cfg.traceability.push({id:uid(),lotId:E('mgTraceLot').value,order:S(E('mgTraceOrder').value),note:S(E('mgTraceNote').value),actor:actor(),at:new Date().toISOString()});audit('RASTREABILIDADE_VINCULADA',cfg.traceability.at(-1));saveConfig(true);render()});E('mgAddLoss')&&(E('mgAddLoss').onclick=()=>{cfg.losses.push({id:uid(),productId:E('mgLossProduct').value,reason:E('mgLossReason').value,qty:N(E('mgLossQty').value),value:N(E('mgLossValue').value),actor:actor(),at:new Date().toISOString()});audit('PERDA_REGISTRADA',cfg.losses.at(-1));saveConfig(true);render()});E('mgAddTask')&&(E('mgAddTask').onclick=()=>{cfg.tasks.push({id:uid(),text:S(E('mgTaskText').value),owner:S(E('mgTaskOwner').value),due:E('mgTaskDue').value,done:false,createdAt:new Date().toISOString()});saveConfig(true);render()});document.querySelectorAll('[data-done-task]').forEach(b=>b.onclick=()=>{const t=cfg.tasks.find(x=>S(x.id)===S(b.dataset.doneTask));if(t){t.done=true;t.doneAt=new Date().toISOString();t.doneBy=actor();audit('TAREFA_CONCLUIDA',t);saveConfig(true);render()}});E('mgAddEq')&&(E('mgAddEq').onclick=()=>{cfg.equipment.push({id:uid(),name:S(E('mgEqName').value),next:E('mgEqNext').value,cost:N(E('mgEqCost').value),createdAt:new Date().toISOString()});saveConfig(true);render()});E('mgAddCheck')&&(E('mgAddCheck').onclick=()=>{cfg.checklistRuns.push({id:uid(),type:E('mgCheckType').value,note:S(E('mgCheckNote').value),actor:actor(),at:new Date().toLocaleString('pt-BR')});audit('CHECKLIST_REGISTRADO',cfg.checklistRuns.at(-1));saveConfig(true);render()});E('mgAsk')&&(E('mgAsk').onclick=()=>E('mgAnswer').textContent=answerQuestion(E('mgQuestion').value));E('mgRepairCatalog')&&(E('mgRepairCatalog').onclick=async()=>{try{await window.johnHydrateStorefrontFromServerV819?.(true);await window.JohnCaseirinhoCatalogSync821?.ensure?.(true);await syncEcommerce('health-repair');toast('Catálogo reconciliado.');await load()}catch(e){toast('Falha ao reconciliar: '+e.message)}});E('mgRunHealth')&&(E('mgRunHealth').onclick=load)}
async function load(){ensurePage();try{const [a,b]=await Promise.all([api('/api/v1/admin/management-engine'),api('/api/v1/admin/management-engine/summary')]);cfg=mergeConfig(a.config||{});summary=b||{};render()}catch(e){cfg=mergeConfig(cfg);summary={...summary,health:{api:false,database:false}};toast('Central Gerencial em modo local: '+e.message);render()}}
async function open(target='cockpit'){tab=TABS.some(x=>x[0]===target)?target:'cockpit';showCenter();await load()}
window.JohnManagement822={open,load,save:saveConfig,syncEcommerce,getConfig:()=>JSON.parse(JSON.stringify(cfg)),canPublishProduct:p=>{const c=channelCalc(p,'ECOMMERCE');return !c.base||c.margin+1e-9>=N(cfg.pricing.minMarginPct)}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(ensurePage,700),{once:true});else setTimeout(ensurePage,400);
